-- Snacks Revoltosos en el Petshop (25 productos: snacks, cajita y combos), con sus fotos, textos y precios.
-- Precio = el de revoltosos.netlify.app el 2026-11-11 + $5.000 (combos también). Desde $70.000 el envío es gratis
-- a toda Colombia (regla general de la tienda), así que no se marca nada aparte.
-- Las fotos están en public/snacks/ (se publican con el sitio). Se cargan 100 unidades de inventario a cada
-- presentación nueva; se ajusta desde el gestor → Productos.
-- Agrega productos.ficha: beneficios, para quién, cómo darlo, preguntas y qué trae cada combo (lo muestra la ficha).
-- Se pega en Supabase → SQL Editor → Run. Se puede correr más de una vez: actualiza textos, fotos y precios sin duplicar.
-- Generado con un script desde el repositorio revoltosos-web; para cambiar algo después, mejor hazlo en el gestor.

alter table public.productos add column if not exists ficha jsonb
  check (ficha is null or (jsonb_typeof(ficha) = 'object' and length(ficha::text) <= 8000));
grant select (ficha) on public.productos to anon, authenticated;
grant insert (ficha), update (ficha) on public.productos to authenticated;

-- Húmero de cerdo deshidratado
insert into public.productos (slug, nombre, categoria, para, tamanos, marca, descripcion, tipo_variante, etiquetas, icono, tono, caracteristicas, fotos, ficha, orden)
values ('humero-de-cerdo', 'Húmero de cerdo deshidratado', 'snacks', '{"perro"}', '{"mediano","grande"}', 'Revoltosos', 'Húmero de cerdo deshidratado lentamente. Un hueso natural para morder, con su sabor de siempre y nada agregado.', null, '{nuevo}', 'cookie', 'peach',
  '[["Ideal para","Perros medianos y grandes · Adultos"],["Ingredientes","Un solo ingrediente"],["Hecho en","Colombia"]]'::jsonb, '{"/snacks/humero-cerdo-producto-600.jpg","/snacks/humero-cerdo-empaque-600.jpg"}', '{"checks":["Para morder","Sin conservantes","100 % natural","Hecho en Colombia"],"beneficios":[["Lo mantiene ocupado","Masticar los calma y los entretiene."],["Ayuda a mantener los dientes","La masticación ayuda a reducir placa y sarro."],["Hueso natural","Sin harinas, sin rellenos, sin colorantes."],["Sin aditivos","Sin conservantes y sin sal añadida."]],"para_quien":["Perros medianos y grandes","Adultos","Perros que disfrutan masticar"],"uso":["Para morder","Premio especial","Enriquecimiento"],"como_darlo":["Siempre bajo supervisión. No lo dejes solo con el hueso.","Retíralo cuando quede pequeño o con puntas, para que no lo trague entero.","Agua fresca a la mano y guárdalo en un lugar fresco y seco."],"preguntas":[["¿Le sirve a un perro pequeño?","Es mejor para perros medianos y grandes. Para los pequeños recomendamos las patas de pollo o las codornices."]]}'::jsonb, 10)
on conflict (slug) do update set nombre = excluded.nombre, descripcion = excluded.descripcion, tipo_variante = excluded.tipo_variante,
  caracteristicas = excluded.caracteristicas, fotos = excluded.fotos, ficha = excluded.ficha, para = excluded.para, tamanos = excluded.tamanos;
insert into public.variantes (producto_id, nombre, codigo, precio, orden)
select p.id, '1 unidad', 'RV-humero-cerdo', 12900, 0 from public.productos p
where p.slug = 'humero-de-cerdo' and not exists (select 1 from public.variantes x where x.producto_id = p.id and x.codigo = 'RV-humero-cerdo');
update public.variantes v set nombre = '1 unidad', precio = 12900, orden = 0
from public.productos p where v.producto_id = p.id and p.slug = 'humero-de-cerdo' and v.codigo = 'RV-humero-cerdo'; -- Revoltosos: 7900

-- Codornices deshidratadas
insert into public.productos (slug, nombre, categoria, para, tamanos, marca, descripcion, tipo_variante, etiquetas, icono, tono, caracteristicas, fotos, ficha, orden)
values ('codornices-deshidratadas', 'Codornices deshidratadas', 'snacks', '{"perro","gato"}', '{"pequeno","mediano","grande"}', 'Revoltosos', 'Codorniz 100 % natural, deshidratada lentamente. Sin conservantes, sin sal y sin colorantes. Crocantes y del tamaño justo para premiar todos los días, a perros y gatos. En bolsa de 50 g para probar o en frasco de 100 g (aprox. 30 codornices).', 'Presentación', '{nuevo}', 'cookie', 'peach',
  '[["Ideal para","Perros de todas las razas · Gatos"],["Ingredientes","Un solo ingrediente"],["Hecho en","Colombia"]]'::jsonb, '{"/snacks/codornices-frasco-100g-600.jpg","/snacks/codornices-bolsa-50g-600.jpg","/snacks/codornices-2-frascos-hero.jpg","/snacks/frasco-100g-y-bolsas.jpg","/snacks/codornicitas-producto-600.jpg"}', '{"checks":["Un solo ingrediente","Sin conservantes","Perros y gatos","Hecho en Colombia"],"beneficios":[["Proteína de verdad","Un solo ingrediente: codorniz entera. Carne magra con mucha proteína."],["Proteína novedosa","Una buena opción si tu mascota no se lleva bien con el pollo o la res."],["Calcio y fósforo naturales","Como incluye el hueso, aporta minerales como calcio, fósforo y zinc."],["Sin aditivos","Sin conservantes, sin sal añadida, sin colorantes."]],"para_quien":["Perros de todas las razas","Gatos","Mascotas con estómago sensible al pollo o la res"],"uso":["Premio diario","Entrenamiento","Topper sobre la comida"],"como_darlo":["De 1 a 3 unidades al día, según el tamaño de tu mascota. Es un premio, no reemplaza su comida.","A los gatos, en trozos pequeños, siempre bajo supervisión y con agua fresca.","Una vez abierto, bien cerrado en un lugar fresco y seco, lejos del sol."],"preguntas":[["¿Le sirve a mi gato?","Sí. Ofrécele trozos pequeños, siempre bajo supervisión y con agua fresca disponible."],["¿Cuántas le doy al día?","De 1 a 3 unidades al día, según el tamaño de tu mascota. Es un premio, no reemplaza su comida."],["¿Bolsa o frasco?","La bolsa de 50 g es para probar. El frasco de 100 g trae aprox. 30 codornices y rinde más."]]}'::jsonb, 1)
on conflict (slug) do update set nombre = excluded.nombre, descripcion = excluded.descripcion, tipo_variante = excluded.tipo_variante,
  caracteristicas = excluded.caracteristicas, fotos = excluded.fotos, ficha = excluded.ficha, para = excluded.para, tamanos = excluded.tamanos;
