  '[["Ideal para","Perros medianos y grandes · Perros que aman morder"],["Ingredientes","Snacks de origen animal deshidratados"],["Hecho en","Colombia"]]'::jsonb, '{"/snacks/femur-cerdo-producto-600.jpg","/snacks/codornices-bolsa-50g-600.jpg","/snacks/femur-cerdo-empaque-600.jpg","/snacks/patas-pollo-empaque-600.jpg"}', '{"checks":["4 snacks distintos","Sin conservantes","Hecho en Colombia"],"beneficios":[["Horas de entretenimiento","Morder y masticar los calma y ayuda a que no muerdan lo que no deben."],["Cuatro texturas","Hueso firme, masticable, crocante y premio: cada día algo distinto."],["Ayuda a mantener los dientes","La masticación ayuda a reducir placa y sarro."],["Sin aditivos","Sin conservantes, sin sal añadida, sin colorantes."]],"para_quien":["Perros medianos y grandes","Perros que aman morder","Adultos"],"uso":["Para morder","Premio diario","Para los días en casa"],"como_darlo":["Un snack a la vez, siempre bajo supervisión.","Retira los huesos cuando queden pequeños o con puntas, para que no los traguen enteros.","Agua fresca a la mano y todo guardado en un lugar fresco y seco."],"preguntas":[["¿Le sirve a un perro pequeño?","Las patas y las codornicitas sí; el fémur va mejor con perros medianos y grandes. Para los pequeños mira el Combo Pollo Loco."]],"trae":[["50 g","Codornicitas","Codorniz deshidratada para premiar todos los días."],["×1","Oído de cerdo","Masticable natural para un buen rato."],["×1","Fémur de cerdo","Un reto para los que muerden fuerte."],["×10","Patas de pollo","Crocantes y fáciles de masticar."]]}'::jsonb, 24)
