insert into public.productos (slug, nombre, categoria, para, tamanos, marca, descripcion, tipo_variante, etiquetas, icono, tono, caracteristicas, fotos, ficha, orden)
values ('cajita-snacks-perros', 'Cajita para perros · 5 snacks', 'snacks', '{"perro"}', '{"pequeno","mediano","grande"}', 'Revoltosos', 'Patas de pollo, oreja de cerdo, codornicitas, codorniz entera y fémur de cerdo en una sola caja. Cinco snacks naturales, deshidratados y sin rellenos, cada uno con su textura: lista para darle o para regalar.', null, '{nuevo}', 'cookie', 'peach',
  '[["Ideal para","Perros de todas las razas · Perros que se aburren rápido"],["Ingredientes","Snacks de origen animal deshidratados"],["Hecho en","Colombia"]]'::jsonb, '{"/snacks/cajita-producto-fondo-blanco-600.jpg","/snacks/cajita-escena.jpg","/snacks/patas-pollo-empaque-600.jpg","/snacks/oreja-cerdo-empaque-600.jpg","/snacks/codorniz-entera-empaque-600.jpg","/snacks/femur-cerdo-empaque-600.jpg"}', '{"checks":["5 snacks distintos","Sin conservantes","Para regalar","Hecho en Colombia"],"beneficios":[["Cinco texturas distintas","De lo crocante a lo duro: cada día algo diferente."],["Proteína animal","Pollo, cerdo y codorniz, sin harinas ni rellenos."],["Sin aditivos","Sin conservantes, sin sal añadida, sin colorantes."]],"trae":[["×5","Patas de pollo","Crocantes y fáciles de masticar."],["×1","Oreja de cerdo","Para masticar un buen rato."],["50 g","Codornicitas","Codorniz deshidratada para premiar."],["×2","Codorniz entera","Carne, piel y hueso en un solo snack."],["×1","Fémur de cerdo","Un reto para los que muerden fuerte."]],"para_quien":["Perros de todas las razas","Perros que se aburren rápido","Un regalo para otro peludo"],"como_darlo":["Un snack a la vez, elegido según el tamaño de tu perro.","Siempre bajo supervisión y con agua fresca a la mano.","Guárdala en un lugar fresco y seco."],"preguntas":[["¿Sirve para perros pequeños?","Sí, con las patas y las codornicitas. El fémur y la oreja son mejores para perros medianos y grandes."],["¿Puedo regalarla?","Claro. Escribe la dirección de quien la va a recibir y avísale antes."]]}'::jsonb, 2)
on conflict (slug) do update set nombre = excluded.nombre, descripcion = excluded.descripcion, tipo_variante = excluded.tipo_variante,
  caracteristicas = excluded.caracteristicas, fotos = excluded.fotos, ficha = excluded.ficha, para = excluded.para, tamanos = excluded.tamanos;
insert into public.variantes (producto_id, nombre, codigo, precio, orden)
select p.id, 'Cajita · 5 snacks', 'RV-cajita-perros', 77900, 0 from public.productos p
where p.slug = 'cajita-snacks-perros' and not exists (select 1 from public.variantes x where x.producto_id = p.id and x.codigo = 'RV-cajita-perros');
update public.variantes v set nombre = 'Cajita · 5 snacks', precio = 77900, orden = 0
from public.productos p where v.producto_id = p.id and p.slug = 'cajita-snacks-perros' and v.codigo = 'RV-cajita-perros'; -- Revoltosos: 72900

-- Combo Codorniz Lover
insert into public.productos (slug, nombre, categoria, para, tamanos, marca, descripcion, tipo_variante, etiquetas, icono, tono, caracteristicas, fotos, ficha, orden)
values ('combo-codorniz-lover', 'Combo Codorniz Lover', 'snacks', '{"perro","gato"}', '{"pequeno","mediano","grande"}', 'Revoltosos', '1 bolsa de codornicitas de 50 g, 1 frasco de codorniz de 100 g, 1 mix de vísceras de 50 g y 1 codorniz entera. Para los que no cambian la codorniz por nada, con el envío incluido.', null, '{nuevo}', 'cookie', 'peach',
  '[["Ideal para","Perros de todas las razas · Gatos · en trozos pequeños"],["Ingredientes","Snacks de origen animal deshidratados"],["Hecho en","Colombia"]]'::jsonb, '{"/snacks/codornices-frasco-100g-600.jpg","/snacks/codornices-bolsa-50g-600.jpg","/snacks/codorniz-entera-empaque-600.jpg"}', '{"checks":["Envío gratis incluido","Todo es codorniz","Para perros y gatos","Hecho en Colombia"],"beneficios":[["Proteína de codorniz","Todo el combo es codorniz: un solo tipo de proteína."],["Proteína novedosa","Una buena opción si tu mascota no se lleva bien con el pollo o la res."],["Calcio y fósforo naturales","La codorniz entera incluye el hueso, que aporta minerales."],["Sin aditivos","Sin conservantes, sin sal añadida, sin colorantes."],["Envío incluido","Llega a tu casa sin pagar envío, a cualquier ciudad de Colombia."]],"para_quien":["Perros de todas las razas","Gatos · en trozos pequeños","Mascotas exigentes con la comida"],"uso":["Premio diario","Topper sobre la comida","Entrenamiento"],"como_darlo":["Ofrécela como premio, sin reemplazar su comida. De 1 a 3 codornicitas al día según su tamaño.","A gatos y perros pequeños, en trozos pequeños y siempre bajo supervisión.","Guárdalo todo bien cerrado en un lugar fresco y seco."],"preguntas":[["¿Le sirve a mi gato?","Sí. Ofrécela en trozos pequeños, siempre bajo supervisión."],["¿Si le sumo otros snacks pago envío?","No. Si tu pedido lleva este combo, todo el pedido viaja sin costo de envío."]],"trae":[["50 g","Codornicitas","Codorniz deshidratada para premiar todos los días."],["100 g","Codorniz en frasco","Aprox. 30 codornicitas en su frasco de 100 g."],["50 g","Mix de vísceras","Vísceras de codorniz deshidratadas: puro sabor."],["×1","Codorniz entera","Carne, piel y hueso en un solo snack."]]}'::jsonb, 31)
on conflict (slug) do update set nombre = excluded.nombre, descripcion = excluded.descripcion, tipo_variante = excluded.tipo_variante,
  caracteristicas = excluded.caracteristicas, fotos = excluded.fotos, ficha = excluded.ficha, para = excluded.para, tamanos = excluded.tamanos;
insert into public.variantes (producto_id, nombre, codigo, precio, orden)
select p.id, 'Único', 'RV-combo-codorniz-lover', 79900, 0 from public.productos p
where p.slug = 'combo-codorniz-lover' and not exists (select 1 from public.variantes x where x.producto_id = p.id and x.codigo = 'RV-combo-codorniz-lover');
update public.variantes v set nombre = 'Único', precio = 79900, orden = 0
from public.productos p where v.producto_id = p.id and p.slug = 'combo-codorniz-lover' and v.codigo = 'RV-combo-codorniz-lover'; -- Revoltosos: 74900

-- Combo Huesos Revoltosos
insert into public.productos (slug, nombre, categoria, para, tamanos, marca, descripcion, tipo_variante, etiquetas, icono, tono, caracteristicas, fotos, ficha, orden)
values ('combo-huesos-revoltosos', 'Combo Huesos Revoltosos', 'snacks', '{"perro"}', '{"mediano","grande"}', 'Revoltosos', '1 bolsa de codornicitas de 50 g, 1 fémur y 1 húmero de res, y 1 fémur y 1 húmero de cerdo. Cuatro huesos para morder todo el mes, con el envío incluido.', null, '{nuevo}', 'cookie', 'peach',
  '[["Ideal para","Perros medianos y grandes · Perros que aman morder"],["Ingredientes","Snacks de origen animal deshidratados"],["Hecho en","Colombia"]]'::jsonb, '{"/snacks/combo-huesos-revoltosos-mvhqfl52vxth.jpg","/snacks/humero-res-empaque-fondo-blanco-600.jpg","/snacks/femur-res-empaque-600.jpg","/snacks/femur-cerdo-empaque-600.jpg","/snacks/humero-cerdo-empaque-600.jpg","/snacks/codornices-bolsa-50g-600.jpg"}', '{"checks":["Envío gratis incluido","4 huesos en un pedido","Sin conservantes","Hecho en Colombia"],"beneficios":[["Horas de entretenimiento","Los huesos los mantienen ocupados y ayudan a que no muerdan lo que no deben."],["Cuatro huesos distintos","Cambia de hueso cada semana para que no se aburra."],["Ayuda a mantener los dientes","La masticación ayuda a reducir placa y sarro."],["Sin aditivos","Sin conservantes, sin sal añadida, sin colorantes."],["Envío incluido","Llega a tu casa sin pagar envío, a cualquier ciudad de Colombia."]],"para_quien":["Perros medianos y grandes","Perros que aman morder","Adultos"],"uso":["Huesos para morder","Para los días en casa","Para regalar"],"como_darlo":["Un snack a la vez, siempre bajo supervisión.","Retira los huesos cuando queden pequeños o con puntas, para que no los traguen enteros.","Agua fresca a la mano y todo guardado en un lugar fresco y seco."],"preguntas":[["¿Le sirve a un perro pequeño?","Los huesos van mejor con perros medianos y grandes. Para los pequeños mira el Combo Pollo Loco."],["¿Si le sumo otros snacks pago envío?","No. Si tu pedido lleva este combo, todo el pedido viaja sin costo de envío."]],"trae":[["50 g","Codornicitas","Codorniz deshidratada para premiar todos los días."],["×1","Fémur de res","Grande y resistente, para mordedores intensos."],["×1","Húmero de res","Grande y firme, para morder con ganas."],["×1","Fémur de cerdo","Un reto para los que muerden fuerte."],["×1","Húmero de cerdo","Hueso natural para morder."]]}'::jsonb, 32)
on conflict (slug) do update set nombre = excluded.nombre, descripcion = excluded.descripcion, tipo_variante = excluded.tipo_variante,
  caracteristicas = excluded.caracteristicas, fotos = excluded.fotos, ficha = excluded.ficha, para = excluded.para, tamanos = excluded.tamanos;
insert into public.variantes (producto_id, nombre, codigo, precio, orden)
select p.id, 'Único', 'RV-combo-huesos-revoltosos', 79900, 0 from public.productos p
