update public.variantes v set nombre = 'Único', precio = 79900, orden = 0
from public.productos p where v.producto_id = p.id and p.slug = 'combo-huesos-revoltosos' and v.codigo = 'RV-combo-huesos-revoltosos'; -- Revoltosos: 74900

-- inventario inicial: 100 de cada presentación que aún no tiene movimientos
insert into public.movimientos (variante_id, cantidad, motivo)
select v.id, 100, 'ingreso' from public.variantes v
where v.codigo like 'RV-%' and not exists (select 1 from public.movimientos m where m.variante_id = v.id);

-- para revisar
select p.orden, p.nombre, v.nombre as presentacion, v.precio, v.stock
from public.productos p join public.variantes v on v.producto_id = p.id
where p.marca = 'Revoltosos' order by p.orden, v.orden;
